(() => {
'use strict';
const builders=new WeakMap();
window.getCardiaContextBuilder=(key,originalBuilder)=>{
 const info=cardiaContextMeta[key];if(!info)return Promise.resolve(originalBuilder);
 if(builders.has(originalBuilder))return builders.get(originalBuilder);
 const request=(async()=>{
  const response=await fetch('assets/context/'+key+'.gz');
  if(!response.ok)throw Error('The regional landmarks could not load.');
  let raw=await response.arrayBuffer();const head=new Uint8Array(raw,0,2);
  if(head[0]===31&&head[1]===139)raw=await new Response(new Blob([raw]).stream().pipeThrough(new DecompressionStream('gzip'))).arrayBuffer();
  const objects=info.parts.map(([fid,name,start,count,faces,length])=>{
   const native=new Int16Array(raw,start,count*3),points=new Float32Array(native.length);
   for(let i=0;i<points.length;i++)points[i]=native[i]*.25*info.scale+info.bias[i%3];
   return {fid,name,skin:fid==='FJ2810',points,indices:new Uint16Array(raw,faces,length)};
  });
  return g=>{
   originalBuilder(g);
   for(const part of objects)g.mesh('context-'+part.fid,part.skin?'skin':'bones',part.skin?'#cfad95':'#d8ceb2',part.points,part.indices,{opacity:part.skin?.09:.29});
  };
 })();
 builders.set(originalBuilder,request);request.catch(()=>builders.delete(originalBuilder));return request;
};
})();
